SELECT SUM(value) AS apac_q2_signups FROM (
  SELECT value FROM (VALUES (13),(118),(257)) AS v(value)
)

SELECT COUNT(*) FILTER (WHERE platform = 'web' AND user_type IS NOT NULL) AS total_users, 
COUNT(*) FILTER (WHERE platform = 'web' AND user_type = 'dark') AS dark_users
FROM dim_users;

SELECT SUM(vm) AS total_value_moments, SUM(opens) AS total_app_opens
FROM (
  SELECT activity__active_date, value AS vm FROM (
    SELECT activity__active_date__day AS activity__active_date, value FROM (
      SELECT * FROM (VALUES
        (date '2026-07-06', 501),(date '2026-07-07',601),(date '2026-07-08',507),(date '2026-07-09',478),(date '2026-07-10',512),(date '2026-07-11',497),(date '2026-07-12',546)
      ) AS t(d,v)
    )
  )
) cross join lateral (
  SELECT * FROM (
    SELECT activity__active_date__day AS d, value FROM (VALUES
      (date '2026-07-06',815),(date '2026-07-07',1032),(date '2026-07-08',854),(date '2026-07-09',826),(date '2026-07-10',876),(date '2026-07-11',804),(date '2026-07-12',863)
    ) AS u(d,v)
  ) WHERE d = activity__active_date
) as opens_tbl(opens)

WITH vm AS (
  SELECT * FROM (VALUES
    (date '2026-07-06', 501),(date '2026-07-07',601),(date '2026-07-08',507),(date '2026-07-09',478),(date '2026-07-10',512),(date '2026-07-11',497),(date '2026-07-12',546)
  ) AS t(activity__active_date, vm)
),
opens AS (
  SELECT * FROM (VALUES
    (date '2026-07-06',815),(date '2026-07-07',1032),(date '2026-07-08',854),(date '2026-07-09',826),(date '2026-07-10',876),(date '2026-07-11',804),(date '2026-07-12',863)
  ) AS u(activity__active_date, opens)
)
SELECT SUM(vm) AS total_value_moments, SUM(opens) AS total_app_opens FROM vm JOIN opens USING(activity__active_date);
